model MichaelisMenten()
  compartment cytosol = 1.0;
  species S in cytosol = 15.0, P in cytosol = 0.0;
  const Vmax = 2.4, Km = 1.8;

  J_cat: S => P; (Vmax * S) / (Km + S);

  S is "Substrate";
  P is "Product";
  J_cat is "Enzymatic Catalysis";
end

model GardnerToggleSwitch()
  compartment cell = 1.0;
  species u in cell = 4.0, v in cell = 0.2;
  const alpha1 = 10.0, alpha2 = 10.0;
  const beta = 2.5, gamma = 2.5;
  const kd_u = 1.0, kd_v = 1.0;

  J_u_syn: => u; alpha1 / (1 + pow(v, beta));
  J_u_deg: u => ; kd_u * u;
  J_v_syn: => v; alpha2 / (1 + pow(u, gamma));
  J_v_deg: v => ; kd_v * v;

  u is "Repressor 1 (LacI)";
  v is "Repressor 2 (TetR)";
end

model SirEpidemicVaccination()
  compartment population = 1.0;
  species S in population = 990.0, I in population = 10.0, R in population = 0.0;
  const beta = 0.00035, gamma = 0.12, vax_frac = 0.35;
  var N_tot = 1000.0;

  J_inf: S => I; beta * S * I;
  J_rec: I => R; gamma * I;

  N_tot := S + I + R;

  E_vax: at (time >= 20.0): S = S * (1.0 - vax_frac), R = R + S * vax_frac;

  S is "Susceptible Individuals";
  I is "Infected Individuals";
  R is "Recovered or Vaccinated Individuals";
end

import "enzymes.ant"

model MetabolicPathway()
  compartment cell = 1.0;
  species $Glc_ext in cell = 20.0;
  species Glc in cell = 5.0, G6P in cell = 0.5, F6P in cell = 0.2, Pyr in cell = 0.1;
  const k_imp = 0.15, V_hk = 3.0, Km_hk = 2.0;
  const kf_pgi = 1.2, kr_pgi = 0.8, k_gly = 0.5, k_out = 0.25;

  J_import: $Glc_ext => Glc; k_imp * Glc_ext;
  J_hexokinase: Glc => G6P; (V_hk * Glc) / (Km_hk + Glc);
  J_isomerase: G6P -> F6P; kf_pgi * G6P - kr_pgi * F6P;
  J_downstream: F6P => Pyr; k_gly * F6P;
  J_export: Pyr => ; k_out * Pyr;

  Glc is "Intracellular Glucose";
  G6P is "Glucose-6-Phosphate";
  F6P is "Fructose-6-Phosphate";
  Pyr is "Pyruvate";
end

